var submit = {!Transaction_Card__c.Submit__c}; 

if (submit === 0) { 
    alert("לא ניתן לאשר את הטופס, שלח טופס חדש ללקוח"); 
} 
else {
    var obj = new sforce.SObject("Transaction_Card__c"); 
    obj.Id= "{!Transaction_Card__c.Id}"; 
    obj.Status__c = 'טופס מאושר'; 
    sforce.connection.update([obj]); 
}

window.location.reload();
